mapper.select:
SELECT id, quiz_title, time_limit_minutes, pass_score, start_time, due_time, attempt_limited, course_id, student_id, teacher_id, display, created_at, updated_at
FROM quizzes
WHERE id = #{quizId}

SELECT id, quiz_title, time_limit_minutes, pass_score, start_time, due_time, attempt_limited, course_id, student_id, teacher_id, display, created_at, updated_at
FROM quizzes
WHERE id = #{quizId}
  AND course_id = #{courseId}

SELECT id, quiz_title, time_limit_minutes, pass_score, start_time, due_time, attempt_limited, course_id, student_id, teacher_id, display, created_at, updated_at
FROM quizzes
WHERE course_id = #{courseId}
  AND student_id = #{studentId}
ORDER BY created_at DESC
